INSERT [dbo].[Peliculas] ([IdPelicula], [Titulo], [Sinopsis], [Genero], [DuracionMinutos], [Anio], [Animo], [IdDirector], [PosterUrl], [IdTMDB]) VALUES (196, N'The Martian', N'Un astronauta intenta sobrevivir solo en Marte.', N'Ciencia ficción', 144, 2015, N'Inspirador', 27, N'https://image.tmdb.org/t/p/w500/hBRK1izFxIH3Nh6vax4ssOHSHVd.jpg', 286217)
